# ---------------------------------------------------------------- Markdown

def md_cell(s):
    return str(s or "").replace("|", "\\|").replace("\n", " ")


def render_md(d, findings, counts, verdict, score):
    p = d["project"]
    plat = p.get("platform", {}) or {}
    scope = p.get("scope", {}) or {}
    s = d.get("summary", {}) or {}
    L = []
    a = L.append
    a(f"# {TITLE} — {p['name']}\n")
    meta = [f"**Date:** {p['review_date']}", f"**Generated:** {generated_stamp()}"]
    if p.get("version"):
        meta.append(f"**Version:** {p['version']}")
    if p.get("reviewer"):
        meta.append(f"**Reviewer:** {p['reviewer']}")
    a(" · ".join(meta) + "  ")
    if plat.get("summary"):
        a(f"**Platform:** {plat['summary']}" + (f" (detection confidence: {plat['detection_confidence']})" if plat.get("detection_confidence") else "") + "  ")
    if scope:
        a("**Scope:** " + (f"{scope['files_reviewed']} first-party files" if scope.get("files_reviewed") is not None else "First-party code")
          + (f", ~{int(scope['first_party_loc']):,} lines" if scope.get("first_party_loc") else "")
          + (f" in {', '.join('`' + x + '`' for x in scope.get('first_party_paths', []))}" if scope.get("first_party_paths") else ""))
    vr, vt, vs = verdict
    a(f"\n## {RAG_EMOJI[vr]} Verdict: {vt}\n\n{vs}\n")
    a(f"| 🔴 Red | 🟠 Amber | 🟢 Green | Total |\n|---|---|---|---|\n| **{counts['red']}** | **{counts['amber']}** | **{counts['green']}** | {len(findings)} |\n")
    a("## Summary\n")
    a(s.get("overview", "") + "\n")
    if s.get("key_risks"):
        a("**Key risks**\n\n" + "\n".join(f"- {x}" for x in s["key_risks"]) + "\n")
    if s.get("strengths"):
        a("**What is working well**\n\n" + "\n".join(f"- {x}" for x in s["strengths"]) + "\n")
    a("## RAG scorecard\n\n| Area | Rating | R | A | G | Coverage |\n|---|---|---|---|---|---|")
    for x in score:
        c = x["counts"]
        covtxt = {"reviewed": "Reviewed", "partial": "Partial", "not_reviewed": "Not reviewed"}[x["status"]]
        a(f"| {x['label']} | {RAG_EMOJI[x['rating']]} {RAG_LABEL[x['rating']]} | {c['red']} | {c['amber']} | {c['green']} | {md_cell(covtxt + (' — ' + x['notes'] if x['notes'] else ''))} |")
    a("")
    reds = [f for f in findings if f["rag"] == "red" and is_open(f)]
    if reds:
        a(f"## 🔴 {MUST_FIX_HEADING}\n\n| ID | Issue | Location | Effort |\n|---|---|---|---|")
        for f in reds:
            a(f"| [{f['id']}](#{f['id'].lower()}) | {md_cell(f['title'])} | `{loc_str(f.get('location'))}` | {f.get('effort', '')} |")
        a("")
    a("## Findings\n")
    for r in RAGS:
        group = [f for f in findings if f["rag"] == r]
        if not group:
            continue
        a(f"### {RAG_EMOJI[r]} {RAG_LABEL[r].title()} — {RAG_MEANING[r]}\n")
        for f in group:
            a(f"#### {f['id']}\n")
            a(f"**{RAG_EMOJI[r]} {RAG_LABEL[r]} · {f['title']}**\n")
            line = [f"**Area:** {CAT_LABEL[f['category']]}", f"**Location:** `{loc_str(f.get('location'))}`",
                    f"**Confidence:** {f['confidence']}"]
            if f.get("effort"):
                line.append(f"**Effort:** {f['effort']}")
            if f.get("status"):
                line.append(f"**Status:** {STATUSES[status_of(f)]}")
            if f.get("origin") == "third-party":
                line.append("**Origin:** Third-party component")
            a(" · ".join(line) + "\n")
            if f.get("origin") == "third-party":
                a("> Third-party component: a published vulnerability or defect in a library this product uses, not in the "
                  "code under review. The description states whether it is compiled in and reachable here.\n")
            if f.get("references"):
                a("**References:** " + ", ".join(f["references"]) + "\n")
            a(f"**What's wrong.** {f['description']}\n")
            a(f"**Field impact.** {f['impact']}\n")
            if f.get("evidence"):
                a("```c\n" + f["evidence"].rstrip() + "\n```\n")
            if f.get("other_locations"):
                a("**Also at:** " + ", ".join(f"`{loc_str(o)}`" for o in f["other_locations"]) + "\n")
            a(f"**Recommendation.** {f['recommendation']}\n")
            res = f.get("resolution") or {}
            if f.get("status") and (res.get("note") or res.get("commit")):
                a(f"**Resolution.** {STATUSES[status_of(f)]}" + (f" — commit `{res['commit']}`" if res.get("commit") else "")
                  + (f" ({res['date']})" if res.get("date") else "") + (f". {res['note']}" if res.get("note") else "") + "\n")
    if d.get("maintainability"):
        a(maintainability_md(d["maintainability"]))
    if d.get("next_steps"):
        a("## Recommended next steps\n\n" + "\n".join(f"{i + 1}. {x}" for i, x in enumerate(d["next_steps"])) + "\n")
    a("## Coverage and method\n")
    if d.get("tools"):
        a("| Tool | Status | Notes |\n|---|---|---|\n" + "\n".join(f"| {md_cell(t.get('name'))} | {t.get('status')} | {md_cell(t.get('notes', ''))} |" for t in d["tools"]) + "\n")
    if scope.get("excluded_paths"):
        a(f"Excluded (vendored / generated): {', '.join('`' + x + '`' for x in scope['excluded_paths'])}. Third-party code was assessed for versions and configuration, not line-by-line.\n")
    a(f"**RAG key:** 🔴 Red — {RAG_MEANING['red']} · 🟠 Amber — {RAG_MEANING['amber']} · "
      f"🟢 Green — {RAG_MEANING['green']} · 🟡 Partial — partly reviewed, nothing found · ⚪ Not assessed — not reviewed.\n")
    a(f"_{DISCLAIMER}_\n")
    a("## Acknowledgements\n\n" + "\n".join(f"- {x}" for x in acknowledgements(d)) + "\n")
    a(f"---\nPrepared by **{BRAND['name']}** — {BRAND['tagline']}. {BRAND['url']} · "
      f"Need help with these findings? [Get in touch]({BRAND['contact_url']}) · {BRAND['phone']} · {BRAND['email']}\n")
    return "\n".join(L)


def write_csv(path, findings):
    with open(path, "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh)
        w.writerow(["ID", "RAG", "Area", "Origin", "Title", "File", "Line", "Confidence", "Effort", "Impact",
                    "Recommendation", "References", "Status", "Owner", "Resolution", "Commit"])
        for f in findings:
            loc = f.get("location") or {}
            w.writerow([f["id"], f["rag"].upper(), CAT_LABEL[f["category"]], ORIGIN_LABEL.get(f.get("origin") or "first-party", "Our code"),
                        f["title"], loc.get("file", ""),
                        loc.get("line") or "", f["confidence"], f.get("effort", ""), f["impact"],
                        f["recommendation"], "; ".join(f.get("references", [])), STATUSES[status_of(f)], "",
                        (f.get("resolution") or {}).get("note", ""), (f.get("resolution") or {}).get("commit", "")])


CI_ENV_VARS = ("CI", "GITHUB_ACTIONS", "GITLAB_CI", "JENKINS_URL", "TF_BUILD",
               "BUILDKITE", "CIRCLECI", "TEAMCITY_VERSION")


def headless_reason():
    """Return why a browser should not be launched, or None if it is fine to."""
    for v in CI_ENV_VARS:
        val = os.environ.get(v, "")
        if val and val.lower() not in ("0", "false", "no"):
            return f"{v} is set (CI environment)"
    if sys.platform.startswith("linux") and not (
            os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY")):
        return "no DISPLAY / WAYLAND_DISPLAY (headless Linux)"
    if os.environ.get("SSH_CONNECTION") and sys.platform != "darwin":
        return "SSH session (browser would open on the remote machine)"
    # Deliberately no isatty() check: tool runners such as Claude Code pipe
    # stdin/stdout even in an interactive session, and that is the main case
    # where the report must open.
    return None


def should_open(force):
    """Decide whether to launch the browser. Returns (open?, reason-if-not)."""
    env = os.environ.get("FW_REVIEW_OPEN", "").strip().lower()
    if env in ("0", "false", "no", "off"):
        return False, "FW_REVIEW_OPEN=0"
    if force or env in ("1", "true", "yes", "on"):
        return True, None
    reason = headless_reason()
    return (reason is None), reason


def open_in_browser(path):
    """Open an HTML file in the user's default browser. Returns True on success.

    Tries the platform opener first (``open`` on macOS, ``os.startfile`` on
    Windows, ``xdg-open`` on Linux) because those respect the user's default
    browser more reliably than the ``webbrowser`` module, then falls back to
    ``webbrowser``. Never raises.
    """
    path = os.path.abspath(path)
    url = pathlib.Path(path).as_uri()
    try:
        if sys.platform == "darwin":
            subprocess.run(["open", path], check=True, timeout=15,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return True
        if sys.platform.startswith("win"):
            os.startfile(path)  # noqa: attribute exists on Windows only
            return True
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            r = subprocess.run(["xdg-open", path], timeout=15,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if r.returncode == 0:
                return True
    except Exception:
        pass
    try:
        return bool(webbrowser.open(url, new=2))
    except Exception:
        return False


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("findings")
    ap.add_argument("--out-dir")
    ap.add_argument("--open", action="store_true",
                    help="open report.html in the default browser after rendering "
                         "(skipped automatically in CI / headless runs)")
    ap.add_argument("--force-open", action="store_true",
                    help="open report.html even when a CI / headless run is detected")
    args = ap.parse_args()
    with open(args.findings, encoding="utf-8") as fh:
        try:
            d = json.load(fh)
        except json.JSONDecodeError as ex:
            sys.exit(f"invalid JSON: {ex}")
    if isinstance(d, dict):
        apply_profile(d)
    errs, warns = validate(d)
    for w in warns:
        print("warning:", w, file=sys.stderr)
    if errs:
        print("findings.json has problems:", file=sys.stderr)
        for x in errs:
            print("  -", x, file=sys.stderr)
        sys.exit(1)
    d = redact_tree(d)
    if _REDACTIONS:
        print(f"redacted {_REDACTIONS} secret value(s) in report text (private keys, quoted credentials, tokens)")
    out = args.out_dir or os.path.dirname(os.path.abspath(args.findings))
    os.makedirs(out, exist_ok=True)
    findings, counts, verdict, score = compute(d)
    with open(os.path.join(out, "report.html"), "w", encoding="utf-8") as fh:
        fh.write(render_html(d, findings, counts, verdict, score))
    with open(os.path.join(out, "report.md"), "w", encoding="utf-8") as fh:
        fh.write(render_md(d, findings, counts, verdict, score))
    write_csv(os.path.join(out, "findings.csv"), findings)
    print(f"Verdict: {verdict[1]} — red {counts['red']}, amber {counts['amber']}, green {counts['green']}")
    for n in ("report.html", "report.md", "findings.csv"):
        print("wrote", os.path.join(out, n))
    if args.open or args.force_open:
        html_path = os.path.join(out, "report.html")
        do_open, why_not = should_open(args.force_open)
        if not do_open:
            print(f"not opening a browser: {why_not}. Report is at",
                  pathlib.Path(os.path.abspath(html_path)).as_uri())
        elif open_in_browser(html_path):
            print("opened", html_path, "in the default browser")
        else:
            print("could not open a browser automatically; open this file manually:",
                  pathlib.Path(os.path.abspath(html_path)).as_uri(), file=sys.stderr)


if __name__ == "__main__":
    main()
